        var pane = Grids.edgeBetween(state.grid, s.pos.x, s.pos.y, target.x, target.y);
        if (((pane >= 0) && (state.grid.edges[Js.Idx(pane)] == Grids.EDGE_WINDOW)) && !state.grid.edgeBoarded.includes(pane))
